/** Remove the complete tenant in one transaction, preserving global accounts. */
export async function purgeDeletedOrgsBefore(cutoff: string): Promise<number> {
  return getDb().transaction((tx) => {
    const expired = tx.select({ id: organizations.id }).from(organizations)
      .where(lte(organizations.archivedAt, cutoff)).all();
    for (const { id } of expired) {
      tx.update(sessions).set({ activeOrgId: null }).where(eq(sessions.activeOrgId, id)).run();
      for (const table of [
        webhookDeliveries, webhookEndpoints, searchIndex, activityEvents,
        notifications, notificationPreferences, attachments, comments, issueLabels,
        issues, labels, projectMembers, projects, invitations, members, invoices,
        subscriptions, organizationUsage, rateLimitBuckets,
      ]) {
        tx.delete(table).where(eq(table.orgId, id)).run();
      }
      tx.delete(organizations).where(eq(organizations.id, id)).run();
    }
    return expired.length;
  });
}
