    expect((await restoreOrganization(tenant.userIds.owner, tenant.org.id)).archivedAt).toBeNull();
    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(getDb().select().from(projects).where(eq(projects.orgId, tenant.org.id)).all()).toHaveLength(1);
    expect(getDb().select().from(activityEvents).where(eq(activityEvents.orgId, tenant.org.id)).all().map(row => row.action))
      .toEqual([\"organization.deleted\", \"organization.restored\"]);
  } finally { detach(); }
});

it(\"expires exactly at the deadline and purges content while retaining users and sessions\", async () => {
  const tenant = await createTenant(\"purge-lifecycle\");
  const db = getDb();
  db.insert(sessions).values({ id: \"purge-session\", userId: tenant.userIds.owner, activeOrgId: tenant.org.id, tokenHash: \"purge-token\", expiresAt: \"2027-01-01T00:00:00.000Z\" }).run();
  db.update(organizations).set({ archivedAt: deletedAt.toISOString() }).where(eq(organizations.id, tenant.org.id)).run();
  await runCleanupArchivedJob(new Date(deadline.getTime() - 1));
  expect(await findOrgById(tenant.org.id)).not.toBeNull();
  vi.useFakeTimers();
  vi.setSystemTime(deadline);
  await expect(restoreOrganization(tenant.userIds.owner, tenant.org.id)).rejects.toBeInstanceOf(NotFoundError);
  await runCleanupArchivedJob(deadline);
  expect(await findOrgById(tenant.org.id)).toBeNull();
  expect(db.select().from(projects).where(eq(projects.orgId, tenant.org.id)).all()).toHaveLength(0);
  expect(db.select().from(members).where(eq(members.orgId, tenant.org.id)).all()).toHaveLength(0);
  expect(db.select().from(users).where(eq(users.id, tenant.userIds.owner)).get()).toBeDefined();
  expect(db.select().from(sessions).where(eq(sessions.id, \"purge-session\")).get()?.activeOrgId).toBeNull();
  await expect(restoreOrganization(tenant.userIds.owner, tenant.org.id)).rejects.toBeInstanceOf(NotFoundError);
});
